mapper.update:
update sys_site_navigation
set menu_key = #{menuKey}, menu_name = #{menuName}, icon = #{icon}, route_path = #{routePath},
    order_num = #{orderNum}, menu_type = #{menuType}, status = #{status}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where navigation_id = #{navigationId}
